// از meta.json و index.html، یک کپشن جذاب تلگرام + عکس بزرگ می‌سازد
const cfg = $('تنظیمات (Config)').item.json;

// --- meta ---
let meta = $('خواندن meta.json').item.json;
if (typeof meta === 'string') { try { meta = JSON.parse(meta); } catch(e){ meta = {}; } }
else if (meta && typeof meta.data === 'string') { try { meta = JSON.parse(meta.data); } catch(e){ meta = {}; } }

// --- html ---
const html = $('خواندن index.html').item.json.data || '';

// عکس شاخص (اولین img با کلاس hero-image)
let hero = '';
const hm = html.match(/<img[^>]*class="hero-image"[^>]*src="images\/([^"]+)"/i)
        || html.match(/<img[^>]*src="images\/([^"]+)"/i);
if (hm) hero = hm[1];
const photo = hero
  ? `https://raw.githubusercontent.com/${cfg.ghOwner}/${cfg.ghRepo}/${cfg.ghBranch}/${cfg.slug}/images/${hero}`
  : '';

// تیزر: چند پاراگراف اول داخل <article> (بدون کپشن عکس)
const artMatch = html.match(/<article[^>]*>([\s\S]*?)<\/article>/i);
const art = artMatch ? artMatch[1] : html;
const re = /<p(?![^>]*class="image-caption")[^>]*>([\s\S]*?)<\/p>/gi;
const paras = [];
let m;
while ((m = re.exec(art)) !== null && paras.length < 3) {
  const t = m[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
  if (t.length > 25) paras.push(t);
}
let teaser = paras.join('\n\n');
const LIMIT = 600;
if (teaser.length > LIMIT) teaser = teaser.slice(0, LIMIT).replace(/\s+\S*$/, '') + '…';
if (!teaser) teaser = meta.blogPostDescription || meta.Excerpt || '';

// لینک درست: /blog/{id عددی}  (نه slug)
let url = cfg.url;
if (!url) url = cfg.id ? `${String(cfg.siteUrl).replace(/\/$/, '')}/blog/${cfg.id}` : (meta.blogPostCanonical || '');

const title = meta.blogPostTitle || meta.Title || '';
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const caption =
  `🚗 <b>${esc(title)}</b>\n\n` +
  `${esc(teaser)}\n\n` +
  `📖 <a href="${url}">ادامه‌ی کامل مقاله در کارماچک 👈</a>`;

return [{ json: { chatId: cfg.tgChat, photo, caption, url, title, hasPhoto: !!photo } }];
